from solution import find_even_Pair
import inspect


def test_issue_example():
    """Example: find_even_Pair([5,4,7,2,1],5) == 4."""
    assert find_even_Pair([5, 4, 7, 2, 1], 5) == 4  # 3 odds, 2 evens: 3*2/2 + 2*1/2 = 3+1=4


def test_issue_all_even():
    """Count the pairs with xor as an even number for all even inputs."""
    assert find_even_Pair([2, 4, 6, 8], 4) == 6  # 4 evens, 0 odds: 4*3/2 + 0 = 6+0=6


def test_issue_all_odd():
    """Count the pairs with xor as an even number for all odd inputs."""
    assert find_even_Pair([1, 3, 5, 7, 9], 5) == 10  # 0 evens, 5 odds: 0 + 5*4/2 = 0+10=10


def test_issue_mixed_parity():
    """Count the pairs with xor as an even number for mixed parity."""
    assert find_even_Pair([1, 2, 3, 4], 4) == 2  # 2 odds, 2 evens: 2*1/2 + 2*1/2 = 1+1=2


def test_issue_no_even_xor():
    """Count the pairs with xor as an even number when parities differ."""
    assert find_even_Pair([1, 2], 2) == 0  # 1 odd, 1 even: 0 + 0 = 0


def test_issue_single_element():
    """Count the pairs with xor as an even number for a single element."""
    assert find_even_Pair([7], 1) == 0  # 1 odd, 0 evens: 0 + 0 = 0


def test_issue_empty_input():
    """Count the pairs with xor as an even number for empty input."""
    assert find_even_Pair([], 0) == 0  # 0 odds, 0 evens: 0 + 0 = 0


def test_issue_zeros_are_even():
    """Count the pairs with xor as an even number when values are zero."""
    assert find_even_Pair([0, 0, 0], 3) == 3  # 3 evens, 0 odds: 3*2/2 + 0 = 3+0=3


def test_issue_negative_numbers():
    """Count the pairs with xor as an even number for negative numbers."""
    assert find_even_Pair([-3, -2, -1, 0], 4) == 2  # 2 odds, 2 evens: 2*1/2 + 2*1/2 = 1+1=2


def test_issue_duplicates():
    """Count the pairs with xor as an even number with duplicate values."""
    assert find_even_Pair([5, 5, 5, 4], 4) == 3  # 3 odds, 1 even: 3*2/2 + 0 = 3+0=3


def test_contract_signature_has_two_params():
    """Public interface is find_even_Pair(A, N) with two parameters."""
    assert len(inspect.signature(find_even_Pair).parameters) == 2  # params A and N: 1+1=2


def test_contract_result_is_int():
    """Count the pairs with xor as an even number returns an int count."""
    assert isinstance(find_even_Pair([1, 2, 3, 4], 4), int) is True  # True means int check passed: 1==1
